require __DIR__.'/config.php';$u=current_user();if(!$u)respond(['error'=>'Sign in to update your profile'],401);if($_SERVER['REQUEST_METHOD']!=='POST')respond(['profile'=>$u]);$in=body();$name=trim($in['name']??$u['name']);$phone=trim($in['phone']??'');$email=strtolower(trim($in['email']??''));$address=trim($in['address']??'');$city=trim($in['city']??'');$province=trim($in['province']??'');if($name==='')respond(['error'=>'Name is required'],422);if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))respond(['error'=>'Enter a valid email address'],422);try{$pdo=db();$s=$pdo->prepare('UPDATE customers SET customer_name=?,phone=?,email=?,address=?,city=?,province=? WHERE cus_id=?');$s->execute([$name,$phone,$email,$address,$city,$province,$u['customer_id']]);$parts=preg_split('/\s+/',trim($name),2);$s=$pdo->prepare('UPDATE users SET full_name=? WHERE user_id=? AND role="Customer"');$s->execute([$name,$u['id']]);$_SESSION['customer_portal_user']['name']=$name;respond(['ok'=>true,'message'=>'Profile updated.']);}catch(Throwable $e){respond(['error'=>'Could not update your profile. Check that the email is not used by another customer.'],500);}
